  color: var(--text-muted);
  margin-top: 0.4rem;
  font-size: 0.95rem;
}

/* ── Form ── */
main { width: 100%; max-width: 660px; }

form { display: flex; flex-direction: column; gap: 1.5rem; }

/* ── form-field (question card) ── */
.form-field {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  transition: border-color var(--transition);
}
.form-field:focus-within { border-color: var(--border-focus); }

.form-field fieldset { border: none; }

.form-field legend {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 0.35rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.question-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.6rem;
  height: 1.6rem;
  background: var(--accent);
  color: #fff;
  border-radius: 50%;
  font-size: 0.78rem;
  font-weight: 700;
  flex-shrink: 0;
}

/* ── Help text ── */
.help-text {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 1rem;
  display: flex;
  align-items: flex-start;
  gap: 0.4rem;
}
.help-text svg { flex-shrink: 0; margin-top: 0.15rem; }

/* ── Choices grid ── */
.choices {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.6rem;
  margin-top: 0.75rem;
}
@media (max-width: 440px) { .choices { grid-template-columns: 1fr; } }

/* ── Checkbox option ── */
