.choice:has(input:focus-visible) {
  outline: 3px solid var(--border-focus);
  outline-offset: 2px;
}

.choice-label { font-size: 0.9rem; line-height: 1.3; }

/* ── Validation ── */
.form-field.has-error { border-color: var(--error); }
.error-msg {
  display: none;
  color: var(--error);
  font-size: 0.82rem;
  margin-top: 0.6rem;
  align-items: center;
  gap: 0.3rem;
}
.form-field.has-error .error-msg { display: flex; }

/* ── Submit button ── */
.actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 0.5rem;
}
.btn-submit {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 0.7rem 2rem;
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
