  outline: 3px solid transparent;
  outline-offset: 2px;
}
.btn-submit:hover { background: var(--accent-hover); }
.btn-submit:focus-visible { outline-color: var(--accent-hover); }
.btn-submit:active { transform: scale(0.97); }

/* ── Results banner ── */
#results {
  display: none;
  margin-top: 2rem;
