 * Computer Languages Quiz — vanilla JS
 * Correct answers are arrays of option values.
 */

const QUESTIONS = [
  {
    id: "q1",
    text: "Which of the following are object-oriented programming languages?",
    help: "Select all that apply. A language qualifies if OOP is a primary supported paradigm.",
    options: [
      { value: "java",    label: "Java" },
      { value: "python",  label: "Python" },
      { value: "c",       label: "C" },
      { value: "haskell", label: "Haskell" },
    ],
    correct: ["java", "python"],
  },
  {
    id: "q2",
    text: "Which languages are statically typed?",
    help: null,
    options: [
      { value: "typescript", label: "TypeScript" },
      { value: "rust",       label: "Rust" },
      { value: "ruby",       label: "Ruby" },
      { value: "javascript", label: "JavaScript" },
    ],
    correct: ["typescript", "rust"],
  },
  {
    id: "q3",
    text: "Which of the following languages are commonly used for systems programming?",
    help: null,
    options: [
      { value: "rust",   label: "Rust" },
      { value: "c",      label: "C" },
      { value: "php",    label: "PHP" },
      { value: "kotlin", label: "Kotlin" },
    ],
    correct: ["rust", "c"],
  },
];

/* ── Build UI ── */
function buildQuiz() {
  const form = document.getElementById("quiz-form");

  QUESTIONS.forEach((q, idx) => {
    const field = document.createElement("div");
    field.className = "form-field";
    field.id = `field-${q.id}`;

    const fieldset = document.createElement("fieldset");
    fieldset.setAttribute("aria-describedby",
      q.help ? `${q.id}-help` : `${q.id}-error`);

    const legend = document.createElement("legend");
    legend.innerHTML =
      `<span class="question-number" aria-hidden="true">${idx + 1}</span>` +
      `<span>${escHtml(q.text)}</span>`;
    fieldset.appendChild(legend);

    if (q.help) {
      const helpP = document.createElement("p");
      helpP.className = "help-text";
      helpP.id = `${q.id}-help`;
      helpP.setAttribute("aria-describedby", `${q.id}-error`);
      helpP.innerHTML =
        `<svg aria-hidden="true" width="14" height="14" viewBox="0 0 16 16" fill="none">
          <circle cx="8" cy="8" r="7" stroke="currentColor" stroke-width="1.5"/>
          <path d="M8 7v5M8 5v.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
        </svg>` +
        escHtml(q.help);
      fieldset.appendChild(helpP);
      fieldset.setAttribute("aria-describedby", `${q.id}-help ${q.id}-error`);
    }

    const grid = document.createElement("div");
    grid.className = "choices";
    grid.setAttribute("role", "group");

    q.options.forEach(opt => {
      const label = document.createElement("label");
      label.className = "choice";
      label.htmlFor = `${q.id}-${opt.value}`;

      const input = document.createElement("input");
      input.type = "checkbox";
      input.id = `${q.id}-${opt.value}`;
      input.name = q.id;
      input.value = opt.value;

      const indicator = document.createElement("span");
      indicator.className = "choice-indicator";
      indicator.setAttribute("aria-hidden", "true");
      indicator.innerHTML =
        `<svg width="10" height="8" viewBox="0 0 10 8" fill="none" aria-hidden="true">
          <path d="M1 4l3 3 5-6" stroke="#fff" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>`;

      const span = document.createElement("span");
      span.className = "choice-label";
      span.textContent = opt.label;

      label.append(input, indicator, span);
      grid.appendChild(label);
    });

    fieldset.appendChild(grid);

    /* inline error */
    const errorSpan = document.createElement("p");
    errorSpan.className = "error-msg";
    errorSpan.id = `${q.id}-error`;
    errorSpan.setAttribute("aria-live", "polite");
    errorSpan.innerHTML =
      `<svg aria-hidden="true" width="12" height="12" viewBox="0 0 16 16" fill="none">
        <circle cx="8" cy="8" r="7" stroke="currentColor" stroke-width="1.5"/>
        <path d="M8 5v4M8 11v.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
      </svg>
      Please select at least one answer.`;
    fieldset.appendChild(errorSpan);

    field.appendChild(fieldset);
    form.insertBefore(field, form.querySelector(".actions"));
  });
}

/* ── Validate & Submit ── */
function handleSubmit(e) {
  e.preventDefault();

  /* clear previous results */
  clearResults();

  let firstInvalid = null;
  let allValid = true;

  QUESTIONS.forEach(q => {
    const field = document.getElementById(`field-${q.id}`);
    const checked = [...document.querySelectorAll(`input[name="${q.id}"]:checked`)]
      .map(cb => cb.value);

    if (checked.length === 0) {
      field.classList.add("has-error");
      allValid = false;
      if (!firstInvalid) firstInvalid = document.querySelector(`input[name="${q.id}"]`);
    } else {
      field.classList.remove("has-error");
    }
  });

  if (!allValid) {
    firstInvalid.focus();
    announce("Some questions are unanswered. Please select at least one option for each question.");
    return;
  }

  /* Score */
  let score = 0;
  QUESTIONS.forEach(q => {
    const checked = new Set(
      [...document.querySelectorAll(`input[name="${q.id}"]:checked`)].map(cb => cb.value)
    );
    const correctSet = new Set(q.correct);

    const isExactMatch =
      checked.size === correctSet.size &&
      [...checked].every(v => correctSet.has(v));

    if (isExactMatch) score++;

    /* Reveal correct / incorrect choices */
    q.options.forEach(opt => {
      const label = document.getElementById(`${q.id}-${opt.value}`).closest(".choice");
      const wasChecked = checked.has(opt.value);
      const isCorrect = correctSet.has(opt.value);

      if (wasChecked && isCorrect)  label.classList.add("correct");
      else if (wasChecked && !isCorrect) label.classList.add("incorrect");
      else if (!wasChecked && isCorrect) label.classList.add("missed");
    });

    /* Disable inputs after submit */
    document.querySelectorAll(`input[name="${q.id}"]`).forEach(cb => cb.disabled = true);
  });

  /* Show results */
  const resultEl = document.getElementById("results");
  resultEl.classList.add("visible");
  resultEl.querySelector(".score").textContent = `${score} / ${QUESTIONS.length}`;
  resultEl.querySelector(".feedback").textContent = feedbackText(score, QUESTIONS.length);
  resultEl.focus();

  announce(`Quiz submitted. You scored ${score} out of ${QUESTIONS.length}. ${feedbackText(score, QUESTIONS.length)}`);

  /* Swap submit to retake */
  const btn = document.getElementById("submit-btn");
  btn.textContent = "Retake Quiz";
  btn.removeEventListener("click", handleSubmit);
  btn.addEventListener("click", resetQuiz);
}

function feedbackText(score, total) {
  const pct = score / total;
  if (pct === 1)   return "Perfect score — well done!";
  if (pct >= 0.67) return "Nice work! Review the highlighted answers to learn more.";
  return "Keep practicing — check the highlighted answers below.";
}

/* ── Reset ── */
function resetQuiz() {
  document.querySelectorAll(".form-field").forEach(f => f.remove());
  document.getElementById("results").classList.remove("visible");
  clearResults();

  const btn = document.getElementById("submit-btn");
  btn.textContent = "Submit Quiz";
  btn.removeEventListener("click", resetQuiz);
  btn.addEventListener("click", handleSubmit);

  buildQuiz();
  document.querySelector("h1").focus();
  announce("Quiz reset. Good luck!");
}

function clearResults() {
  document.querySelectorAll(".choice").forEach(c => {
    c.classList.remove("correct", "incorrect", "missed");
  });
  document.querySelectorAll(".form-field").forEach(f => f.classList.remove("has-error"));
}

/* ── Live region helper ── */
function announce(msg) {
  const lr = document.getElementById("live-region");
  lr.textContent = "";
  requestAnimationFrame(() => { lr.textContent = msg; });
}

/* ── Tiny HTML escape ── */
function escHtml(str) {
  return str.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
}

/* ── Boot ── */
document.addEventListener("DOMContentLoaded", () => {
  buildQuiz();
  document.getElementById("submit-btn").addEventListener("click", handleSubmit);
});
