/* ── Validate & Submit ── */
function handleSubmit(e) {
  e.preventDefault();

  /* clear previous results */
  clearResults();

  let firstInvalid = null;
  let allValid = true;

  QUESTIONS.forEach(q => {
    const field = document.getElementById(`field-${q.id}`);
    const checked = [...document.querySelectorAll(`input[name="${q.id}"]:checked`)]
      .map(cb => cb.value);

    if (checked.length === 0) {
      field.classList.add("has-error");
      allValid = false;
      if (!firstInvalid) firstInvalid = document.querySelector(`input[name="${q.id}"]`);
    } else {
      field.classList.remove("has-error");
    }
  });

  if (!allValid) {
    firstInvalid.focus();
    announce("Some questions are unanswered. Please select at least one option for each question.");
    return;
  }

  /* Score */
  let score = 0;
  QUESTIONS.forEach(q => {
    const checked = new Set(
      [...document.querySelectorAll(`input[name="${q.id}"]:checked`)].map(cb => cb.value)
    );
    const correctSet = new Set(q.correct);

    const isExactMatch =
      checked.size === correctSet.size &&
      [...checked].every(v => correctSet.has(v));

    if (isExactMatch) score++;

    /* Reveal correct / incorrect choices */
    q.options.forEach(opt => {
      const label = document.getElementById(`${q.id}-${opt.value}`).closest(".choice");
      const wasChecked = checked.has(opt.value);
      const isCorrect = correctSet.has(opt.value);

      if (wasChecked && isCorrect)  label.classList.add("correct");
      else if (wasChecked && !isCorrect) label.classList.add("incorrect");
      else if (!wasChecked && isCorrect) label.classList.add("missed");
    });

    /* Disable inputs after submit */
    document.querySelectorAll(`input[name="${q.id}"]`).forEach(cb => cb.disabled = true);
  });

