+/**
+ * Computer Languages Quiz — vanilla JS
+ * Correct answers are arrays of option values.
+ */
+
+const QUESTIONS = [
+  {
+    id: "q1",
+    text: "Which of the following are object-oriented programming languages?",
+    help: "Select all that apply. A language qualifies if OOP is a primary supported paradigm.",
+    options: [
+      { value: "java",    label: "Java" },
+      { value: "python",  label: "Python" },
+      { value: "c",       label: "C" },
+      { value: "haskell", label: "Haskell" },
+    ],
+    correct: ["java", "python"],
+  },
+  {
+    id: "q2",
+    text: "Which languages are statically typed?",
+    help: null,
+    options: [
+      { value: "typescript", label: "TypeScript" },
+      { value: "rust",       label: "Rust" },
+      { value: "ruby",       label: "Ruby" },
+      { value: "javascript", label: "JavaScript" },
+    ],
+    correct: ["typescript", "rust"],
+  },
+  {
+    id: "q3",
+    text: "Which of the following languages are commonly used for systems programming?",
+    help: null,
+    options: [
+      { value: "rust",   label: "Rust" },
+      { value: "c",      label: "C" },
+      { value: "php",    label: "PHP" },
+      { value: "kotlin", label: "Kotlin" },
+    ],
+    correct: ["rust", "c"],
+  },
+];
+
+/* ── Build UI ── */
+function buildQuiz() {
+  const form = document.getElementById("quiz-form");
+
+  QUESTIONS.forEach((q, idx) => {
+    const field = document.createElement("div");
+    field.className = "form-field";
+    field.id = `field-${q.id}`;
+
+    const fieldset = document.createElement("fieldset");
+    fieldset.setAttribute("aria-describedby",
+      q.help ? `${q.id}-help` : `${q.id}-error`);
+
+    const legend = document.createElement("legend");
+    legend.innerHTML =
+      `<span class="question-number" aria-hidden="true">${idx + 1}</span>` +
+      `<span>${escHtml(q.text)}</span>`;
+    fieldset.appendChild(legend);
+
+    if (q.help) {
+      const helpP = document.createElement("p");
+      helpP.className = "help-text";
+      helpP.id = `${q.id}-help`;
+      helpP.setAttribute("aria-describedby", `${q.id}-error`);
+      helpP.innerHTML =
+        `<svg aria-hidden="true" width="14" height="14" viewBox="0 0 16 16" fill="none">
+          <circle cx="8" cy="8" r="7" stroke="currentColor" stroke-width="1.5"/>
+          <path d="M8 7v5M8 5v.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
+        </svg>` +
+        escHtml(q.help);
+      fieldset.appendChild(helpP);
+      fieldset.setAttribute("aria-describedby", `${q.id}-help ${q.id}-error`);
+    }
+
+    const grid = document.createElement("div");
+    grid.className = "choices";
+    grid.setAttribute("role", "group");
+
+    q.options.forEach(opt => {
+      const label = document.createElement("label");
+      label.className = "choice";
+      label.htmlFor = `${q.id}-${opt.value}`;
+
+      const input = document.createElement("input");
+      input.type = "checkbox";
+      input.id = `${q.id}-${opt.value}`;
+      input.name = q.id;
+      input.value = opt.value;
+
+      const indicator = document.createElement("span");
+      indicator.className = "choice-indicator";
+      indicator.setAttribute("aria-hidden", "true");
+      indicator.innerHTML =
+        `<svg width="10" height="8" viewBox="0 0 10 8" fill="none" aria-hidden="true">
+          <path d="M1 4l3 3 5-6" stroke="#fff" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
+        </svg>`;
+
+      const span = document.createElement("span");
+      span.className = "choice-label";
+      span.textContent = opt.label;
+
+      label.append(input, indicator, span);
+      grid.appendChild(label);
